import{_ as s,o as t,c as a,a7 as o}from"./chunks/framework.xMNG87v2.js";const g=JSON.parse('{"title":"Worlds","description":"World formats Axolotl-PM can load, including Bedrock LevelDB and converted Java 1.12 worlds, and how to add existing worlds or generate new ones.","frontmatter":{"title":"Worlds","outline":"deep","description":"World formats Axolotl-PM can load, including Bedrock LevelDB and converted Java 1.12 worlds, and how to add existing worlds or generate new ones.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/worlds"}]]},"headers":[],"relativePath":"docs/worlds.md","filePath":"docs/worlds.md","lastUpdated":1790689997000}'),l={name:"docs/worlds.md"};function i(n,e,d,r,p,h){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="worlds" tabindex="-1">Worlds <a class="header-anchor" href="#worlds" aria-label="Permalink to &quot;Worlds&quot;">​</a></h1><p>Axolotl-PM supports several world formats.</p><p>Unlike a vanilla server, it also supports loading several worlds at the same time. This is useful to offer a more varied game experience to your players without transferring them between servers, as well as allowing players to have unlimited space in game modes like SkyBlock.</p><h2 id="supported-world-formats" tabindex="-1">Supported world formats <a class="header-anchor" href="#supported-world-formats" aria-label="Permalink to &quot;Supported world formats&quot;">​</a></h2><p>Axolotl-PM saves worlds in the same format as vanilla Bedrock by default.</p><p>However, it has some support for several other world formats.</p><table tabindex="0"><thead><tr><th>Type</th><th>Format</th><th>Support</th><th>Notes</th></tr></thead><tbody><tr><td>Java &lt;= 1.12.x</td><td>McRegion/Anvil</td><td>Converted on load</td><td>Some blocks may display incorrectly</td></tr><tr><td>Bedrock &lt;= 1.18.20</td><td>LevelDB</td><td>Direct</td><td>Some blocks may not be supported</td></tr><tr><td>Bedrock &gt;= 1.18.30</td><td>LevelDB</td><td>Direct</td><td>Some blocks may not be supported<br>Entities may not load</td></tr><tr><td>PM3</td><td>PMAnvil</td><td>Converted on load</td><td>Will be converted on load</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Error</p><p>Java 1.13+ worlds are <strong>not</strong> currently supported (as of 5.37.2) due to extensive changes to the format compared to Java 1.12.</p></div><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>While Axolotl-PM cannot load <code>.mcworld</code> files by default, it can load the world files inside if you manually extract them. You can do this by changing the file extension to <code>.zip</code> and extracting it as a zip.</p></div><h2 id="generating-new-worlds" tabindex="-1">Generating new worlds <a class="header-anchor" href="#generating-new-worlds" aria-label="Permalink to &quot;Generating new worlds&quot;">​</a></h2><p>Axolotl-PM has a very basic world generator. This is because it hasn’t been a focus of our development team.</p><p>Biomes usually appear as large blobs, and seeds from vanilla Minecraft won’t produce the same results in Axolotl-PM.</p><p>Worlds configured in <code>server.properties</code> or <code>pocketmine.yml</code> will be generated according to the preferred settings if they aren’t found.</p><h2 id="adding-pre-existing-worlds" tabindex="-1">Adding pre-existing worlds <a class="header-anchor" href="#adding-pre-existing-worlds" aria-label="Permalink to &quot;Adding pre-existing worlds&quot;">​</a></h2><p>Worlds must be placed in the <code>worlds</code> folder in folder form.</p><p>Normally, worlds will have a <code>level.dat</code> file inside their folder. In order for Axolotl-PM to detect the world, the folder structure should look like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>worlds</span></span>
<span class="line"><span>|___ my_world</span></span>
<span class="line"><span>    |___ level.dat</span></span>
<span class="line"><span>|___ my_world_2</span></span>
<span class="line"><span>    |___ level.dat</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Just putting the worlds in the folder is not enough to make Axolotl-PM load them.</p><p>You also need to configure them in <code>pocketmine.yml</code> (see below).</p></div><h2 id="loading-multiple-worlds-at-once" tabindex="-1">Loading multiple worlds at once <a class="header-anchor" href="#loading-multiple-worlds-at-once" aria-label="Permalink to &quot;Loading multiple worlds at once&quot;">​</a></h2><p>You can load multiple worlds by configuring them in <code>pocketmine.yml</code>.</p><p>Opening the file in a text editor, you’ll find a section like this near the bottom:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">worlds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  #These settings will override the generator set in server.properties and allows loading multiple worlds</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  #Example:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  #world: #Folder name of the world inside the worlds folder</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # seed: 404</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # generator: FLAT</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # preset: 2;bedrock,59xstone,3xdirt,grass;1</span></span></code></pre></div><p>These settings work similarly to those in <code>server.properties</code>, but you can add multiple entries.</p><p>If we wanted to load all of the worlds shown in the example in the previous section, it might look like this:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">worlds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  my_world</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    seed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123456</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    generator</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">FLAT</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  my_world_2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    seed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">arandomstring</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    generator</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DEFAULT</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>All of the options (<code>seed</code>, <code>generator</code>, etc.) are optional. If they aren’t specified, the server will use built-in defaults.</p></div><h2 id="changing-the-default-world" tabindex="-1">Changing the default world <a class="header-anchor" href="#changing-the-default-world" aria-label="Permalink to &quot;Changing the default world&quot;">​</a></h2><p>The default world’s name is controlled by the <code>level-name</code> option in <code>server.properties</code>.</p><p>This option corresponds to the name of the folder inside the <code>worlds</code> folder to be used as the default world.</p><p>For example, if <code>level-name</code> is set to <code>my-awesome-world</code>, Axolotl-PM will look for <code>worlds/my-awesome-world/level.dat</code> to load the world.</p><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>If no world exists by the given name, a new one will be generated using the options set in <code>level-type</code>, <code>level-seed</code> and <code>generator-settings</code> options.</p></div><h2 id="teleporting-between-worlds" tabindex="-1">Teleporting between worlds <a class="header-anchor" href="#teleporting-between-worlds" aria-label="Permalink to &quot;Teleporting between worlds&quot;">​</a></h2><p>As of 5.37.2, there is currently no built-in way to teleport between worlds in Axolotl-PM.</p><p>However, plugins can teleport player between worlds easily.</p><p>You can find plugins on <a href="https://poggit.pmmp.io/plugins" target="_blank" rel="noreferrer">Poggit</a> for managing and teleporting between worlds.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Poggit is now read-only. Existing plugins can still be found there, but no new plugins or updates are being published.</p></div>`,36)])])}const k=s(l,[["render",i]]);export{g as __pageData,k as default};
